function uuidV7Date(uuid) {
  const hex = uuid.replace(/-/g, '').slice(0, 12);
  return new Date(parseInt(hex, 16));
}

console.log(uuidV7Date('018f3c2e-7a10-7d4e-9b3a-2f6c1e8d9a50').toISOString());

const uuidV4orV7 = /^[0-9a-f]{8}-[0-9a-f]{4}-[47][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

console.log(uuidV4orV7.test('3b241101-e2bb-4255-8caf-4136c566a962')); // true
console.log(uuidV4orV7.test('018f3c2e-7a10-7d4e-9b3a-2f6c1e8d9a50')); // true
